// Throwaway diagnostic script — NOT part of the repo.
// Tests PR #116's Einstein wiring by calling the exact `EinsteinAPI` class from
// node_modules/@salesforce/retail-react-app/app/hooks/use-einstein.js (verbatim, unmodified
// logic — constructor/_buildBody/_constructEinsteinProduct/einsteinFetch/sendViewProduct/
// getRecommendations/getRecommenders copied line-for-line), instantiated with `dnt: false` so
// it bypasses the browser DNT-cookie gate entirely and hits the real endpoint. This isolates
// "is our request construction (recommender name, product/body shape, auth header) correct"
// from "does the DNT gate block it" and "is Einstein deployed for Zimmermann" — both of which
// are separate, already-documented blockers.
//
// Only addition vs the real class: one console.log of the raw HTTP status in einsteinFetch,
// because the real method swallows non-ok statuses into `{}` and Tim's test is specifically
// about the status code.

import fs from 'node:fs'
import path from 'node:path'

const PROJECT_ROOT = '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa'

function readEnvVar(file, key) {
    const p = path.join(PROJECT_ROOT, file)
    if (!fs.existsSync(p)) return undefined
    const line = fs.readFileSync(p, 'utf8').split('\n').find((l) => l.startsWith(`${key}=`))
    return line ? line.slice(key.length + 1).trim() : undefined
}

// Same resolution order the real app uses (tier .env wins over base .env in switchEnv.mjs).
const siteId = readEnvVar('.env.dev', 'EINSTEIN_API_SITE_ID') ?? readEnvVar('.env', 'EINSTEIN_API_SITE_ID')

// ---- Verbatim from node_modules/@salesforce/retail-react-app/app/hooks/use-einstein.js ----
class EinsteinAPI {
    constructor({host, einsteinId, siteId, isProduction, dnt}) {
        this.dnt = dnt
        this.siteId = siteId
        this.isProduction = isProduction
        this.host = host
        this.einsteinId = einsteinId
    }

    _buildBody(params) {
        const instanceType_prd = 'prd'
        const instanceType_sbx = 'sbx'
        const body = {...params}
        if (this.siteId) {
            body.realm = this.siteId.split('-')[0]
        }
        body.instanceType = this.isProduction ? instanceType_prd : instanceType_sbx
        return body
    }

    _constructEinsteinProduct(product) {
        if (product.type) {
            if (product.type.variant) {
                return {id: product.master.masterId, price: product.price, sku: product.id}
            }
            if (product.type.variationGroup) {
                return {
                    altId: product.id,
                    id: product.master.masterId,
                    price: product.price,
                    sku: product.id,
                    type: 'vgroup'
                }
            }
            return {id: product.id, price: product.price}
        }
        if (product.hitType) {
            return {id: product.productId, sku: product.productId, altId: '', altIdType: ''}
        }
        return {id: product.id, sku: '', altId: '', altIdType: ''}
    }

    async einsteinFetch(endpoint, method, body) {
        if (this.dnt !== false) return {}

        const headers = {
            'Content-Type': 'application/json',
            'x-cq-client-id': this.einsteinId
        }
        if (body) {
            body = this._buildBody(body)
        }

        let response
        try {
            response = await fetch(`${this.host}/v3${endpoint}`, {
                method,
                headers,
                ...(body && {body: JSON.stringify(body)})
            })
        } catch (error) {
            console.log(`  → FETCH THREW: ${error.message}`)
            return {}
        }

        console.log(`  → HTTP ${response.status} ${response.statusText}`) // diagnostic only, not in the real class

        if (!response?.ok) {
            return {}
        }
        try {
            return await response.json()
        } catch (error) {
            console.log(`  → JSON parse failed: ${error.message}`)
            return {}
        }
    }

    async sendViewProduct(product, args) {
        const endpoint = `/activities/${this.siteId}/viewProduct`
        const body = {product: this._constructEinsteinProduct(product), ...args}
        return this.einsteinFetch(endpoint, 'POST', body)
    }

    async getRecommenders() {
        return this.einsteinFetch(`/personalization/recommenders/${this.siteId}`, 'GET', null)
    }

    async getRecommendations(recommenderName, products, args) {
        const endpoint = `/personalization/recs/${this.siteId}/${recommenderName}`
        const body = {products: products?.map((p) => this._constructEinsteinProduct(p)), ...args}
        return this.einsteinFetch(endpoint, 'POST', body)
    }
}
// ---- end verbatim section ----

// Same recommender-name constant PR #116 actually calls
// (EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED, node_modules/@salesforce/retail-react-app/app/constants.js:160)
const RECOMMENDER_NAME = 'viewed-recently-einstein'

async function main() {
    console.log(`siteId resolved from .env.dev/.env: ${siteId ?? '(undefined)'}\n`)

    const einstein = new EinsteinAPI({
        host: 'https://api.cquotient.com',
        einsteinId: '1ea06c6e-c936-4324-bcf0-fada93f83bb1', // config/default.js:153, unchanged
        siteId,
        isProduction: false, // config/default.js:158
        dnt: false // forced — this is what a real shopper's browser would need DNT consent to produce
    })

    const cookieId = `sfcc-hooktest-${Date.now()}`
    console.log(`Using fresh test cookieId: ${cookieId}\n`)

    console.log('1) getRecommenders() — confirms the recommender exists on this siteId')
    const recommenders = await einstein.getRecommenders()
    const match = recommenders?.recommenders?.find((r) => r.name === RECOMMENDER_NAME)
    console.log(`   recommender "${RECOMMENDER_NAME}" configured: ${Boolean(match)}${match ? ` (type: ${match.recommenderType})` : ''}\n`)

    console.log(`2) getRecommendations("${RECOMMENDER_NAME}", [], {cookieId}) — baseline, before any view`)
    const before = await einstein.getRecommendations(RECOMMENDER_NAME, [], {cookieId})
    console.log(`   products returned: ${JSON.stringify(before?.recs?.map((r) => r.id) ?? before)}\n`)

    console.log('3) sendViewProduct({id: "25519318M"}, {cookieId}) — real demo-catalog product, same cookieId')
    await einstein.sendViewProduct({id: '25519318M'}, {cookieId})
    console.log()

    console.log(`4) getRecommendations("${RECOMMENDER_NAME}", [], {cookieId}) again — same cookieId, immediately after the view`)
    const after = await einstein.getRecommendations(RECOMMENDER_NAME, [], {cookieId})
    console.log(`   products returned: ${JSON.stringify(after?.recs?.map((r) => r.id) ?? after)}\n`)

    console.log('5) waiting 5s, then sendViewProduct + re-fetch again, in case of propagation delay')
    await new Promise((r) => setTimeout(r, 5000))
    await einstein.sendViewProduct({id: '25519318M'}, {cookieId})
    const after2 = await einstein.getRecommendations(RECOMMENDER_NAME, [], {cookieId})
    console.log(`   products returned: ${JSON.stringify(after2?.recs?.map((r) => r.id) ?? after2)}\n`)

    console.log('6) same, with a brand-new product id (12416789M-adjacent baseline swapped for a fresh guess) and fresh cookieId, to rule out this specific product id being stale on the demo catalog')
    const cookieId2 = `sfcc-hooktest2-${Date.now()}`
    console.log(`   fresh cookieId: ${cookieId2}`)
    const baseline2 = await einstein.getRecommendations(RECOMMENDER_NAME, [], {cookieId: cookieId2})
    console.log(`   baseline: ${JSON.stringify(baseline2?.recs?.map((r) => r.id) ?? baseline2)}`)
}

